-- seed_motor_specs_100.sql -- 100 spek dari database_spek_motor_motorkita_100.xlsx
-- Buat tabel motor_specs jika belum ada (dipakai halaman admin Spek Motor + Motor Saya).

create table if not exists motor_specs (
  id uuid primary key default gen_random_uuid(),
  brand text not null,
  model text not null,
  type text check (type in ('matic','manual','kopling')) not null default 'matic',
  oli text,
  volume_oli text,
  ban_depan text,
  ban_belakang text,
  aki text,
  busi text,
  catatan text,
  created_at timestamptz default now(),
  unique (brand, model)
);
alter table motor_specs enable row level security;
drop policy if exists "public read specs" on motor_specs;
create policy "public read specs" on motor_specs for select using (true);
drop policy if exists "admin write specs" on motor_specs;
create policy "admin write specs" on motor_specs for all using (
  exists (select 1 from profiles where profiles.id = auth.uid() and profiles.role = 'admin')
) with check (
  exists (select 1 from profiles where profiles.id = auth.uid() and profiles.role = 'admin')
);


select count(*) as motor_specs_total from motor_specs;